     1	/**
     2	 * Event Service Client for Expo/React Native
     3	 * Fetches events from local API server (server-side Ticketmaster calls)
     4	 * This avoids exposing API keys in the client
     5	 */
     6	
     7	// Local API server URL - MUST use host LAN IP for physical iPhone
     8	// The server runs on the host machine and Expo Go on iPhone needs the host IP
     9	const API_BASE_URL = 'http://192.168.68.101:8080';
    10	
    11	const TIMEOUT = 15000;
    12	
    13	/**
    14	 * Fetch events from local API server
    15	 * The server handles Ticketmaster API calls with the stored API key
    16	 */
    17	async function fetchFromAPI(endpoint = '/events') {
    18	  try {
    19	    const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    20	      method: 'GET',
    21	      headers: {
    22	        'Accept': 'application/json',
    23	        'Content-Type': 'application/json',
    24	      },
    25	    });
    26	    
    27	    if (!response.ok) {
    28	      console.warn(`[EventService] API error: ${response.status}`);
    29	      return null;
    30	    }
    31	    
    32	    return await response.json();
    33	  } catch (error) {
    34	    console.warn(`[EventService] Network error: ${error.message}`);
    35	    return null;
    36	  }
    37	}
    38	
    39	/**
    40	 * Fetch Ticketmaster events from local API server
    41	 */
    42	export async function fetchTicketmasterEventsViaServer() {
    43	  const data = await fetchFromAPI('/events');
    44	  
    45	  if (!data || !data.ticketmaster) {
    46	    console.warn('[EventService] No data from API server');
    47	    return [];
    48	  }
    49	  
    50	  if (data.ticketmaster.error) {
    51	    console.warn(`[EventService] Ticketmaster error: ${data.ticketmaster.error}`);
    52	    return [];
    53	  }
    54	  
    55	  return data.ticketmaster.events || [];
    56	}
    57	
    58	/**
    59	 * Fetch all events (Ticketmaster + other sources)
    60	 */
    61	export async function fetchAllEventsViaServer() {
    62	  const data = await fetchFromAPI('/events');
    63	  
    64	  if (!data) {
    65	    return { events: [], error: 'API unavailable' };
    66	  }
    67	  
    68	  const allEvents = [];
    69	  
    70	  // Add Ticketmaster events
    71	  if (data.ticketmaster?.events) {
    72	    allEvents.push(...data.ticketmaster.events.map(e => ({ ...e, source: 'ticketmaster' })));
    73	  }
    74	  
    75	  // Add Kulturhuset events
    76	  if (data.otherSources?.sources?.kulturhuset) {
    77	    allEvents.push(...data.otherSources.sources.kulturhuset.map(e => ({ ...e, source: 'kulturhuset' })));
    78	  }
    79	  
    80	  // Add Malmö Live events
    81	  if (data.otherSources?.sources?.malmolive) {
    82	    allEvents.push(...data.otherSources.sources.malmolive.map(e => ({ ...e, source: 'malmolive' })));
    83	  }
    84	  
    85	  return {
    86	    events: allEvents,
    87	    count: allEvents.length,
    88	    ticketmasterCount: data.ticketmaster?.count || 0,
    89	  };
    90	}
    91	
    92	/**
    93	 * Health check for API server
    94	 */
    95	export async function checkAPIHealth() {
    96	  const data = await fetchFromAPI('/health');
    97	  
    98	  if (!data) {
    99	    return { connected: false, error: 'Cannot reach API server' };
   100	  }
   101	  
   102	  return {
   103	    connected: true,
   104	    status: data.status,
   105	    ticketmasterKey: data.ticketmasterKey,
   106	  };
   107	}
   108	
   109	// Export for use in App.js
   110	export const fetchEvents = fetchAllEventsViaServer;
   111	export { API_BASE_URL };
